parameters.jsCode:
const body = $('Webhook Gestrif Lead').item.json.body || $('Webhook Gestrif Lead').item.json || {};

// Helper: Title Case
function toTitleCase(str) {
  if (!str) return '';
  const stopWords = ['de', 'da', 'do', 'dos', 'das', 'e', 'em', 'para', 'com'];
  return str
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((w, idx) => {
      const lower = w.toLowerCase();
      if (idx > 0 && stopWords.includes(lower)) return lower;
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    })
    .join(' ');
}

// 1. Column A: Unique Lead ID (e.g. GEST-9B4X2Z)
const id = 'GEST-' + Math.random().toString(36).substring(2, 8).toUpperCase();

// 2. Column B: Formatted Date/Time (DD/MM/YYYY HH:mm:ss)
const now = new Date();
const data = now.toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
}).replace(',', '');

// 3. Column C: Name (Clean Title Case)
const nome = toTitleCase(body.name || '');

// 4. Column D: Institution (Clean Title Case or Default)
const instituicao = toTitleCase(body.institution || '') || 'Não informada';

// 5. Column E: E-mail (Trim & Lowercase)
const email = String(body.email || '').trim().toLowerCase();

// 6. Column F: Phone (Formatted with leading apostrophe ' to force Sheets text formatting)
let rawPhone = String(body.phone || '').trim();
let formattedPhone = rawPhone;
if (rawPhone && !rawPhone.startsWith('+') && rawPhone.replace(/\D/g, '').length >= 9) {
  formattedPhone = '+' + rawPhone;
}
// Prepend single quote (') so Google Sheets never evaluates it as a formula
const telefone = formattedPhone ? ("'" + formattedPhone.replace(/^'+/, '')) : '';

// 7. Column G: Origin
const origem = body.source ? String(body.source).trim() : 'Website Gestrif';

// Return STRICTLY columns A~G:
return {
  json: {
    "id": id,
    "Data": data,
    "Nome": nome,
    "Instituição": instituicao,
    "E-mail": email,
    "Telefone": telefone,
    "Origem": origem
  }
};
